// ---------- v100: Season 2 finale, Kevin Slides, Horsemen Chronicles 2-5 ----------
{
  const add = (id, extra) => Object.assign(CHARACTERS[id] || (CHARACTERS[id] = { title: extra.title, sections: [] }), extra.top || {}, { sections: [...(CHARACTERS[id].sections || []), ...extra.sections] });
  add("blackwood:yuki", { sections: [{ h: "Spoilers: the Outside (episode 20)", b: "Yuki walks past the Ring Road and finds the world gone, then learns she is dead too: she remembers no flat and no street, only the office. She takes the scythe from [[blackwood:grim-reaper|the Reaper]] by killing her, at the Reaper's own request, and inherits the office. Her last act of the season is to sit on the floor of the common room and ask Lux what she wants." }, { h: "In Kevin Slides", b: "She appears in the spinoff as a scattered figure: priestess, tax inspector, barista, bounty hunter, driver and gardener, all pieces of one person lost through the Seam, who come home when Kevin says please." }] });
  add("blackwood:grim-reaper", { sections: [{ h: "Spoilers: Imogen Vale (episode 20)", b: "Death is an office, not a person. The woman in the coat was **Imogen Vale**, a nineteen-year-old who took her own life in 1987 and was handed the scythe by the **Ark of 144**. Every Reaper was one. She hid the end of the world behind a university, and when [[blackwood:yuki|Yuki]] found out she refused the Assignor's order to stop her, gave up the office, and asked Yuki to end it. Her last words were *Tell my mother I took my shoes off*. She left a letter in the handle: *Ask them. Even if they say fine. Ask again.*" }, { h: "In Kevin Slides", b: "Her mother, a small Yorkshire woman in a floral apron, has posted her a casserole every year for seven hundred years because the Reaper never opened one. Opening the last, with [[blackwood:kevin|Kevin]]'s help, shows it was only ever dinner." }] });
  add("blackwood:madison", { sections: [{ h: "Spoilers: the first death (episode 20)", b: "Madison Ashworth died at nine, in the park, when she gave [[blackwood:ena|Ena]] a cupcake: touching the unstable luminous core killed her instantly, and the core went into the only thing that had ever been kind to it. For eleven years Madison has been Ena's body and Ena her heart. She still does not know." }] });
  add("blackwood:ena", { sections: [{ h: "Spoilers: the core (episode 20)", b: "Ena had been told all her short life that anyone who touched her would die. The designation in the Reaper's file is simply **ENA**, an unstable luminous core, and it survived Madison's death by living inside her." }] });
  add("blackwood:kevin", { sections: [{ h: "Kevin Slides", b: "In the four-episode spinoff the Reaper hands him a sentient cardboard parcel and ten minutes at a time to deliver it across the multiverse. He says please to everything, which breaks spells, offends the dead, and ends up saving most of the worlds he lands in. His translucent spare, [[blackwood:kevina|Kevina]], is the best part of the trip. In **Forwarding Address** he finds out that every Yuki he has met was her." }] });
  CHARACTERS["blackwood:kevina"] = { title: "Kevina", aka: ["Co-courier"], role: "Translucent spare of Kevin", firstIn: "bw-kevin-slides-2", sections: [{ h: "Who she is", b: "A floor attendant at Mortality Services for nineteen years until the Parcel stitched her together from every Kevin who ever stopped to say please. Translucent, carries a mop, and is the only one who can eat in the Reaper's kitchen. She is promoted to co-courier, and goes home through a door marked STAFF ONLY at the end of **Forwarding Address**, asking only that Kevin wipe the coffee ring." }] };
  CHARACTERS["blackwood:the-parcel"] = { title: "The Parcel", aka: ["Box"], role: "Sentient cardboard box", firstIn: "bw-kevin-slides-1", sections: [{ h: "Who it is", b: "A box posted in 1347 by the Reaper's mother that only speaks when somebody says please. A counter on its side shows ten minutes until the next slide. It cries, and says it is condensation." }] };
  CHARACTERS["blackwood:reapers-mother"] = { title: "The Reaper's Mother", aka: ["Mum"], role: "Mother of Death", firstIn: "bw-kevin-slides-1", sections: [{ h: "Who she is", b: "The oldest mother in the world: small, round, silver-haired, Yorkshire, in a floral apron. She can make any room a kitchen, sends tuna noodle bake by post, and signs each note *Love, Mum*. She told Yuki in 1352 that Kevin has the manners of a golden retriever and the persistence of a hornet." }] };
  CHARACTERS["blackwood:imogen-vale"] = { title: "Imogen Vale", role: "The Grim Reaper, before the coat", firstIn: "bw-ep20", sections: [{ h: "Who she was", b: "Nineteen in 1987 and \"quiet for a very long time\". Her story is told in **The Outside**, and ends with a pair of shoes left side by side like a beach, and a hoodie three sizes too small. See [[blackwood:grim-reaper|The Grim Reaper]]." }] };
  CHARACTERS["blackwood:assignor"] = { title: "The Assignor", role: "Envoy of the Ark of 144", firstIn: "bw-ep20", sections: [{ h: "What it is", b: "A tall faceless figure in white, a burning **144** on its chest, speaking in a hundred soft voices. The salt-white ground follows it. It says the Ark is not the enemy, shows Yuki a staircase of a hundred and forty-three robed figures and an empty hundred and forty-fourth step, and leaves her a question: *someone must ask them what they want.* What the Ark is has not been explained." }] };
  CHARACTERS["blackwood:warden"] = { title: "The Warden", role: "Giant keeper of the outside", firstIn: "bw-kevin-slides-3", sections: [{ h: "Who it is", b: "A ten-storey giant at Hell's Peak Estates who has kept the outside outside for four hundred years. Nobody had said please to it before Kevin. It carries the boy Tom away on its shoulder." }] };
  CHARACTERS["blackwood:steve-acting-director"] = { title: "Steve", role: "Acting Director of Regional Paperwork", firstIn: "bw-kevin-slides-4", sections: [{ h: "Who he is", b: "Mortality Services management, and the one who tells Kevin about the mandatory please memo and the unclaimed mop in the supply cupboard." }] };
}
CONCEPTS.push(
  { id: "blackwood:the-outside", kind: "place", title: "The outside", body: "What lies beyond the Ring Road in **The Outside**: ash, glass, rusted cars with the doors open, plastic chairs outside a petrol station with a skeleton in each. The world stopped before the first day of term. Blackwood is the only place left." },
  { id: "blackwood:ring-road", kind: "place", title: "The Ring Road", body: "The circle of road around campus, with a white line and three stencilled words: DO NOT CROSS. Nobody had ever walked into the fog beyond it until Yuki." },
  { id: "blackwood:the-seam", kind: "concept", title: "The Seam", body: "The thing that holds Blackwood together as a place instead of a grave. When the truth is spoken the sky cracks like plaster. In **Kevin Slides** it is also where Yuki was scattered, and where the End of Paperwork waits." },
  { id: "blackwood:ark-of-144", kind: "concept", title: "The Ark of 144", body: "Unexplained. Signs the letters that assign Reapers and sends the Assignor. Its message at the end of Season 2: *Congratulations on your promotion. Your probation begins now.*" },
  { id: "blackwood:second-chance", kind: "concept", title: "The second chance", body: "What Blackwood is for: a lifeboat for people who died in pain. Everyone on campus is already dead, which is why nobody stays dead after the football." },
  { id: "blackwood:imogens-letter", kind: "concept", title: "Imogen's letter", body: "Folded in the hatch in the base of the scythe. *It isn't a magic word. It doesn't fix anything. But it's the only door I ever found that opened from the outside.*" },
  { id: "blackwood:please", kind: "concept", title: "Please", body: "The rule of **Kevin Slides**: saying it breaks spells, wakes the Parcel, frees a scarecrow, calms a giant and, said together by Kevin and Yuki, denies the End of Paperwork's request to close the world." },
  { id: "blackwood:hells-peak-estates", kind: "place", title: "Hell's Peak Estates", body: "A cul-de-sac where [[blackwood:lux|Lux]] and [[blackwood:velvette|Velvette]] are married and run the HOA. The by-laws are walls against the apocalypse: no unscheduled arrivals, no unapproved packages, no please. Madison runs the Welcome Wagon." },
  { id: "blackwood:hereafter-revenue-service", kind: "place", title: "The Hereafter Revenue Service", body: "Kevin Slides, episode two. Breathing is illegal. Yuki is Chief Inspector, the Printer is the Judge, and the Reaper's Mother is the Commissioner." },
  { id: "blackwood:the-last-stop-motel", kind: "place", title: "The Last Stop", body: "A motel where Sugar Rush is a bounty hunter and the Reaper learns the Parcel is from her mother." },
  { id: "blackwood:the-reapers-kitchen", kind: "place", title: "The Reaper's kitchen", body: "Whatever the Reaper's Mother wants the office to be: yellow wallpaper, copper pans, a cat on the windowsill, a tomato plant, and a pine shelf of hundreds of unopened parcels." },
  { id: "blackwood:end-of-paperwork", kind: "concept", title: "The End of Paperwork", body: "Every form ever filled in, ten thousand years of boxes ticked, pressing through the Seam. If it gets through it files everything. Kevin and Yuki answer its NOTICE OF CLOSURE with *please*, and the reply comes in Mum's handwriting: APPLICATION DENIED. HAVE A LOVELY DAY." },
);
{
  const tl = TIMELINES.blackwood, i = tl.findIndex((r) => r[1] === "bw-madison-nomad");
  tl.splice(i < 0 ? tl.length : i, 0,
    ["Season 2 finale", "bw-ep20", "Yuki crosses the Ring Road, finds the end of the world, and learns what Blackwood is."],
    ["Spinoff", "bw-kevin-slides-1", "Kevin gets a sentient box and ten minutes."],
    ["Spinoff", "bw-kevin-slides-2", "On trial for breathing."],
    ["Spinoff", "bw-kevin-slides-3", "Hell's Peak Estates: no please allowed."],
    ["Spinoff", "bw-kevin-slides-4", "The parcel is opened; Yuki comes home."]);
}
{
  const s = SERIES_LORE.blackwood.sections;
  s.push({ h: "Kevin Slides", b: "A four-episode spinoff in the vein of *Sliders*: [[blackwood:kevin|Kevin]] and [[blackwood:kevina|Kevina]] fall through worlds with a sentient parcel, saying please to everything. Episodes: **Return to Sender**, **The Dead Letter Office**, **Hell's Peak Estates** and **Forwarding Address**." });
  s.push({ h: "Spoilers: what Blackwood is", b: "**The Outside** (Season 2 finale) reveals that the world has ended, that everyone at Blackwood is already dead, and that the Reapers are people who died by suicide, assigned by the [[blackwood:ark-of-144|Ark of 144]]. The campus is a second chance for people who died in pain. It carries a content warning and contains no method detail." });
}

// ---------- v101: Lux & Velvette: Nine Courses ----------
{
  const add = (id, extra) => Object.assign(CHARACTERS[id] || (CHARACTERS[id] = { title: extra.title, sections: [] }), extra.top || {}, { sections: [...(CHARACTERS[id].sections || []), ...extra.sections] });
  add("blackwood:lux", { sections: [{ h: "Nine Courses", b: "On their tenth anniversary she hides behind a forty-foot table and a nine-course dinner, because she has to confess that in first year she **forged Velvette's scholarship** and arranged for her roommate to leave, so that Velvette would need her. Her question since childhood (*if I make someone love me, does it count?*) is answered by the one person she could never arrange. She proposes with a ring set with Gerald, Velvette's confiscated ruler." }] });
  add("blackwood:velvette", { sections: [{ h: "Nine Courses", b: "She worked out the forgery by week three and stayed: *nobody had ever lied to me to keep me alive.* She kills a poisoned soup, an oyster bomb and four snipers on her anniversary, says yes to a ring made from [[blackwood:gerald|Gerald]], and tells Lux the whole of it **counts**." }] });
  CHARACTERS["blackwood:marguerite-ashdown"] = { title: "Dean Marguerite Ashdown", role: "Dean of Lakewood", affiliation: "Lakewood University", firstIn: "bw-lux-velvette", sections: [{ h: "Who she is", b: "Grey suit, grey pearls, grey eyes, a face like a closed filing cabinet. She has tried to buy [[blackwood:lux|Lux]] out since Lux was twenty-three, and in **Nine Courses** stages a poisoned dinner as a 'negotiation' to learn whether Lux would sacrifice Velvette for Blackwood. She wouldn't, and Marguerite asks to be invited to the wedding." }] };
  CHARACTERS["blackwood:gerald"] = { title: "Gerald", role: "Velvette's first knife", firstIn: "bw-ep08", sections: [{ h: "What he is", b: "A sharpened plastic ruler confiscated in third grade and returned in **Finders Keepers**. Velvette wears him on her chain. In **Nine Courses** Lux has him set in silver as an engagement ring." }] };
  CONCEPTS.push({ id: "blackwood:nine-courses", kind: "concept", title: "Nine Courses", body: "[[blackwood:lux|Lux]] and [[blackwood:velvette|Velvette]]'s tenth-anniversary dinner: amuse-bouche, soup, fish, sorbet, interval, roast, cheese, dessert and the bill. Each course is an ambush, a confession or a ceremony. The long table is shortened by thirty-eight feet at the end." });
  SERIES_LORE.blackwood.sections.push({ h: "Lux & Velvette: Nine Courses", b: "A standalone adult spinoff (rated R) set in the penthouse on [[blackwood:lux|Lux]] and [[blackwood:velvette|Velvette]]'s tenth anniversary. Lakewood's [[blackwood:marguerite-ashdown|Dean Ashdown]] tries to buy their marriage; Lux confesses what she did to keep Velvette; Velvette tells her it counts. It ends in a proposal, a ring made of [[blackwood:gerald|Gerald]], and a very short table." });
}

// ---------- v102: Sasha: Fine Print ----------
{
  const add = (id, extra) => Object.assign(CHARACTERS[id] || (CHARACTERS[id] = { title: extra.title, sections: [] }), extra.top || {}, { sections: [...(CHARACTERS[id].sections || []), ...extra.sections] });
  add("blackwood:sasha", { sections: [{ h: "Fine Print", b: "In the spinoff about her she drafts [[blackwood:lux|Lux]] and [[blackwood:velvette|Velvette]]'s forty-one-clause marriage agreement overnight (its Clause 14 treats [[blackwood:gerald|Gerald]] as a person), turns down a job from [[blackwood:marguerite-ashdown|Dean Ashdown]] but keeps the card, and refuses, for now, to sign **the Second Schedule**, which would make her the Advocate. Lux finally tells her *I couldn't have done it without you*, and she witnesses the wedding and walks Lux down the aisle." }] });
  CHARACTERS["blackwood:second-schedule"] = { title: "The Second Schedule", role: "Document, the Advocate's clause", firstIn: "bw-sasha", sections: [{ h: "What it is", b: "A thick cream-coloured document in a black folder that speaks in the dry voice of a bailiff. It is the clause every contract between the living and the dead traces back to, and it says it left every loophole [[blackwood:sasha|Sasha]] found there on purpose. Signing it makes her the **Advocate**, holding power of attorney for everyone at Blackwood who is dead or will be." }] };
  CONCEPTS.push({ id: "blackwood:advocate", kind: "concept", title: "The Advocate", body: "The office of last resort between the living and the dead at Blackwood, held for four hundred years by a lawyer now reduced to a precedent. The Second Schedule offers it to [[blackwood:sasha|Sasha]]. She says: after the wedding, then Monday." });
  SERIES_LORE.blackwood.sections.push({ h: "Sasha: Fine Print", b: "A standalone spinoff (rated R) set the night before [[blackwood:lux|Lux]] and [[blackwood:velvette|Velvette]]'s wedding, told from the lawyer's desk. It follows [[blackwood:sasha|Sasha]] through the agreement, a midnight offer from Lakewood and the Second Schedule, and ends on the lawn at Hell's Peak Estates, where a very short vow is said: *thank you. Please be happy.*" });
}

// ---------- v103: Episode 21, The Hundred and Forty-Four ----------
{
  const add = (id, extra) => Object.assign(CHARACTERS[id] || (CHARACTERS[id] = { title: extra.title, sections: [] }), extra.top || {}, { sections: [...(CHARACTERS[id].sections || []), ...extra.sections] });
  add("blackwood:assignor", { sections: [{ h: "Spoilers: the Ark (episode 21)", b: "Built by the Ark on a bad night out of leftover parts and grief, and never taught to stop being polite. It reports that it did not stop Yuki: *I asked her what she wanted.*" }] });
  CHARACTERS["blackwood:simone-adeyemi-park"] = { title: "Simone Adeyemi-Park", role: "Chair of the Ark of 144", firstIn: "bw-ep21", sections: [{ h: "Who she is", b: "Six hundred years old, close-cropped grey hair, a thin silver ring and her sister's grey wool coat with a missing button. A thermal engineer on Meridian Station, she locked the door on nine hundred and sixty thousand people, including her sister and her eleven-year-old daughter Imani. She wrote the rule that no one finds the person they loved before. Her opening narration is the first-person account of the end of everything." }, { h: "Imogen", b: "She realised three days before the meeting that [[blackwood:imogen-vale|Imogen Vale]], whom she picked for the scythe, had her daughter's handwriting and her own mouth. *I handed my own child the scythe.*" }] };
  CHARACTERS["blackwood:dr-halvorsen"] = { title: "Dr. Helen Halvorsen", role: "Surgeon of the Ark", firstIn: "bw-ep21", sections: [{ h: "Who she is", b: "Cold, clipped and the loudest voice for keeping the harvest going. She never says sorry, because she knows what she would owe: she chose the first terror, a dark room, for her seven-year-old daughter Sofia, who was too happy to give the Ark any warmth. Sofia is the first light in the lattice." }] };
  CHARACTERS["blackwood:tobias"] = { title: "Tobias", role: "Born aboard the Ark", firstIn: "bw-ep21", sections: [{ h: "Who he is", b: "Nineteen, shaved head, stolen tracksuit three sizes too big, and the only one who has never seen the sky. He finds out what the Ark burns and says it aloud in the room. His wish: *to be warm, and for nobody else to be cold.*" }] };
  for (const [id, title, role, b] of [
    ["kwabena", "Kwabena", "Treasurer of the Ark", "A courteous man in a dark suit who states the thermodynamics plainly: the warmth of the dead is made by grief. His wish is to be forgiven."],
    ["anselm", "Brother Anselm", "Priest of the Ark", "In a worn collar at the back. *Let us be corpses.* His wish is to have said no."],
    ["old-ruth", "Old Ruth", "Oldest of the 144", "Small as a walnut, delighted and terrible. She wants to see a star, and she is the one who sits with Dr. Halvorsen at the end."],
    ["marisol", "Marisol", "Engineer of the Ark", "Holds the seam together and tracks the lattice. She wants to stop being so tired."],
    ["peony", "Peony", "Of the 144", "Pink cardigan and a smile that does not blink, insisting everything is going very well, until she says sorry to a little girl she heard through the pipes."],
  ]) CHARACTERS["blackwood:" + id] = { title, role, firstIn: "bw-ep21", sections: [{ h: "Who they are", b }] };
  CONCEPTS.push(
    { id: "blackwood:the-cold", kind: "concept", title: "The Cold", body: "The eleven days in which the last warmth failed on the Ark and a hundred and forty-four people died down to thirty, until a door knocked three times and the afterlife, which had never been part of the universe, let them in." },
    { id: "blackwood:the-lattice", kind: "place", title: "The Lattice", body: "A cathedral turned inside out, walled with a hundred and four thousand lamps, each one a soul, around the heart of the Ark. The brightest point in it is [[blackwood:lux|Lux]] and [[blackwood:velvette|Velvette]], nine lives running." },
    { id: "blackwood:the-hundred-and-forty-fourth-chair", kind: "concept", title: "The hundred and forty-fourth chair", body: "The cushioned chair on the inner ring that nobody sits in. It belongs to Imogen Vale, who was Imani, Simone's daughter." },
  );
  SERIES_LORE.blackwood.sections.push({ h: "Spoilers: The Hundred and Forty-Four (episode 21)", b: "The universe ended billions of years before anyone predicted. A hundred and forty-four people on a station locked the doors, froze, and were let into the afterlife next door, which gives off the only heat left, and the heat is made by grief. They built Blackwood as a harvest that keeps its dead hopeful and apart. The dead who died in the dark are not there; they are still in the cold. The meeting ends with every one of them saying what they want, a vote to answer [[blackwood:yuki|Yuki]], and a note on the glass: *PLEASE. COME IN. SIT. THERE IS A CHAIR FOR YOU.*" });
}

// ---------- v104: Episode 22, A Chair for You ----------
{
  const add = (id, extra) => Object.assign(CHARACTERS[id] || (CHARACTERS[id] = { title: extra.title, sections: [] }), extra.top || {}, { sections: [...(CHARACTERS[id].sections || []), ...extra.sections] });
  add("blackwood:yuki", { sections: [{ h: "A Chair for You (episode 22)", b: "She climbs the staircase, sits in the empty hundred-and-forty-fourth chair and drinks the undrinkable tea. She refuses to forgive the Ark but agrees to listen, and takes on telling the hundred and four thousand sleepers the truth. She opens the door on Sofia's room with the scythe, which, it turns out, is for **opening**; the harvest was a later improvisation." }] });
  add("blackwood:dr-halvorsen", { sections: [{ h: "Sorry", b: "She finally gives Yuki Sofia's drawing and asks her to open the door. When the first lamp in the lattice goes out and a soft green one takes its place, she kneels at the foot of the engine and says *I'm sorry* until Simone holds her." }] });
  add("blackwood:lux", { sections: [{ h: "Nine lives (episode 22)", b: "Woken by Yuki, she goes straight past the awful news to the question that matters: *who the hell are you, and what have you done to my school?* She tells Simone she has been dreaming of a grey coat for nine lives." }] });
  CHARACTERS["blackwood:sofia-halvorsen"] = { title: "Sofia Halvorsen", role: "Dr. Halvorsen's daughter", firstIn: "bw-ep22", sections: [{ h: "Who she is", b: "Seven, in a pyjama top much too big, kept for five hundred and ninety-eight years in the first terror her mother built. She was very good and made no noise because she thought her mother would come. Yuki opens the wall, and a brown dog with eight unlikely legs, Biscuit, runs across a field to her." }] };
  CHARACTERS["blackwood:biscuit"] = { title: "Biscuit", role: "Sofia's dog", firstIn: "bw-ep22", sections: [{ h: "Who he is", b: "The best dog, drawn with eight legs because Sofia couldn't do four. He is waiting in the field." }] };
  CONCEPTS.push({ id: "blackwood:the-first-room", kind: "place", title: "The First Room", body: "The first terror the Ark made: four walls, a mattress, a tin plate and a rabbit with one ear. It held Sofia for five hundred and ninety-eight years, until the scythe opened the wall." });
  SERIES_LORE.blackwood.sections.push({ h: "A Chair for You (episode 22)", b: "The Ark asks [[blackwood:yuki|Yuki]] to do the one thing they never did: tell the hundred and four thousand the truth and ask what they want. She won't forgive them, only listen. A hundred and forty-three people say *we let it happen*, one at a time. [[blackwood:dr-halvorsen|Dr. Halvorsen]] gets her daughter out of the dark, and [[blackwood:lux|Lux]] wakes up to ask who they are." });
}

// ---------- v105: Episode 23, What Do You Want ----------
{
  const add = (id, extra) => Object.assign(CHARACTERS[id] || (CHARACTERS[id] = { title: extra.title, sections: [] }), extra.top || {}, { sections: [...(CHARACTERS[id].sections || []), ...extra.sections] });
  add("blackwood:yuki", { sections: [{ h: "What Do You Want (non-canon)", b: "She tells the hundred and four thousand they are dead, one sleeper at a time and then the whole hall, and asks each what they want. She cannot decide for them; she can only open a door. At the end she uses the scythe to open a door to a blue dawn, closes it again and says *not yet*: she wants to be there when the last one is ready." }] });
  add("blackwood:simone-adeyemi-park", { sections: [{ h: "The button", b: "A ten-year-old in a unicorn onesie sews a button on her grey coat, which had been missing one for six hundred years, using a needle and thread from Simone's mother's tin. Then the dead vote on whether the warmth should go on, and Simone asks *why* they would say yes after what the Ark did. [[blackwood:lux|Lux]] answers: *because you asked.*" }] });
  CHARACTERS["blackwood:daniel"] = { title: "Daniel", role: "First sleeper Yuki wakes", firstIn: "bw-noncanon-want", sections: [{ h: "Who he is", b: "Sixteen, school blazer, a bruise yellowing under one eye. He remembers a doorway and being cold, and the first person Yuki tells. He seconds Peony's motion to hold a vote." }] };
  CHARACTERS["blackwood:unicorn-girl"] = { title: "The girl in the unicorn onesie", role: "Ten years old", firstIn: "bw-noncanon-want", sections: [{ h: "Who she is", b: "She sews on Simone's missing button, offers her a cuddle (*it's only a button*) and counts the hands in the vote, giving up at *a lot*." }] };
  CONCEPTS.push({ id: "blackwood:the-vote", kind: "concept", title: "The vote of the dead", body: "A hundred and four thousand people raise their hands to keep the warmth going, honest this time and by choice. Around nine thousand refuse at first, arms folded, and raise them last. The harvest from then on is only what is given." });
  SERIES_LORE.blackwood.sections.push({ h: "What Do You Want (non-canon)", b: "**Not canon.** An alternate continuation of Episode 22. [[blackwood:yuki|Yuki]] wakes and tells the whole campus the truth and asks what they want, one hundred and four thousand times. They vote with raised hands to keep the Ark's warmth alive, on one condition: nothing is taken any more. The episode ends on a message on the glass: *THANK YOU FOR ASKING. WE'LL TAKE IT FROM HERE. — S.*" });
}

// ---------- v106: Incarnate: Book Two · The Salt and the Seam ----------
{
  const add = (id, extra) => Object.assign(CHARACTERS[id] || (CHARACTERS[id] = { title: extra.title, sections: [] }), extra.top || {}, { sections: [...(CHARACTERS[id].sections || []), ...extra.sections] });
  add("incarnate:ena", { sections: [{ h: "Book Two: The Salt and the Seam", b: "On the drowned water world of **Pelagia**, Ena lives in a leaning ironwood stilt-house at Salt-Reach with [[incarnate:eri|Eri]], carrying a white knife-scar in her sternum, a left arm blackened to the elbow by shards, and severe PTSD and **Dissociative Identity Disorder (DID)**. She keeps a hemp-bound salt ledger tied to her belt so the four alters sharing her head can leave notes across time loss: **Ena** (the exhausted host), **[[incarnate:harumi|Harumi]]** (the feral protector/persecutor who holds the memories of the knife and the laundromat), **[[incarnate:sunny|Sunny]]** (a seven-year-old child alter stuck on the Sunday before Himo climbed through the kitchen window), and **[[incarnate:kio-soldier|Kio]]** (a near-mute soldier fragment who checks knots three times and scrubs the black arm with pumice and brine). At the bottom of the drained abyssal salt-basin she and all four parts of her system kneel co-consciously before [[incarnate:tim|Tim]]'s barnacle-covered stone statue, carve *TIM. BROTHER. I'M SORRY. ME TOO.* into the plinth, and tip Marguerite's last tin of shards into the boiling fault." }] });
  add("incarnate:eri", { sections: [{ h: "Book Two: The Salt and the Seam", b: "On Pelagia, Eri walks on crooked whalebone-and-ironwood shin-splints and a heavy ironwood crutch from the Nursery floor (**Sorry**), with an empty left eye socket (**Experiment**) and a scarred right eye (**Vessel**). Haunted by stripping Lute's songs into a jar and by Siren wearing her body, she wears brine-stiffened leather gloves so her bare skin never touches a mind uninvited. She learns how to ground each of Ena's alters (singing Lute's bridge-song to Sunny, trading sharp truths with Harumi, counting bolts with Kio), confronts Siren and the hollowed remnant of Calypso in the lighthouse cellar, and wedges her broken legs into the collapsing basalt trench rim to haul Ena out by her blackened wrist." }] });
  CHARACTERS["incarnate:harumi"] = { title: "Harumi", role: "Protector and persecutor alter in Ena's system", firstIn: "inc-b1a1", sections: [{ h: "Who she is", b: "Formed when Tim plunged the kitchen knife into Ena's chest and the corruption flooded the wound. Coarse, profane, dryly protective, she carries the rage and the memories of the resistance, Dov in the laundromat (**Relapse**), and Chimera on the highway (**Prophecy**) so Ena doesn't die of them. In **Book Two: The Salt and the Seam**, Esme helps Eri and Ena see that Harumi is not a parasitic vessel: she is the protector who kept the body alive, and at Tim's stone statue in the tide she finally weeps openly through Ena's eyes." }] };
  CHARACTERS["incarnate:sunny"] = { title: "Sunny", role: "Seven-year-old child alter in Ena's system", firstIn: "inc-b2", sections: [{ h: "Who she is", b: "Stuck on a Sunday morning before Himo climbed through the kitchen window (**Plan B**). She counts things in twos and sevens, hums her mother Asa's river song, draws her half-eared orange cat Tim in white chalk on the stilt-house floorboards, and shares a peeled salt-orange with [[incarnate:famine|Famine]] in the cliff sea-cave." }] };
  CHARACTERS["incarnate:kio-soldier"] = { title: "Kio (The Soldier)", role: "Tactical gatekeeper alter in Ena's system", firstIn: "inc-b2", sections: [{ h: "Who she is", b: "Formed in the Nursery corridors and the First War trenches. Fronts during extreme physical pain, cold water immersion, or sensory overload, checking rope knots three times, scrubbing the blackened left arm with pumice and brine, and speaking only in three-word tactical reports or old Anti-tongue (*Soi*, *Kio*, *Oistoi*)." }] };
  CONCEPTS.push(
    { id: "incarnate:pelagia", kind: "place", title: "Pelagia (The Water World)", body: "The slate-grey ocean world where the remnants of the collapse washed up in **Book Two: The Salt and the Seam**: black basalt skerries, the leaning ironwood stilt-house at **Salt-Reach**, the floating ship-rib ring of **The Drift-Weir**, Rui and Tsui's **Cliff of Oranges**, the **Glass Shoals** lighthouse, and the six-mile abyssal trench." },
    { id: "incarnate:hemp-ledger", kind: "concept", title: "The hemp-bound salt ledger", body: "Tied to Ena's belt with hemp twine on Pelagia so Ena, Harumi, Kio, and Sunny can communicate across dissociative amnesia and blackouts." },
    { id: "incarnate:drift-weir", kind: "place", title: "The Drift-Weir", body: "A floating ring of lashed ship-ribs, stone breakwater blocks, and tarps on Pelagia where [[incarnate:wren|Wren]], Pip, [[incarnate:esme|Esme]], and [[incarnate:pia|Pia]] survive in **Book Two: The Salt and the Seam**." },
    { id: "incarnate:cliff-of-oranges", kind: "place", title: "The Cliff of Oranges", body: "A volcanic basalt cliff on Pelagia where [[incarnate:rui|Rui]] tends dwarf salt-orange trees warmed by thermal vents and carries a net bag of oranges up the steps every week to [[incarnate:tsui|Tsui]]'s whitewashed stone cottage, while [[incarnate:famine|Famine]] and Death shelter in the sea-cave behind the orchard." },
    { id: "incarnate:glass-shoals", kind: "place", title: "The Glass Shoals Lighthouse", body: "A black stone lighthouse ringed with chalk wards above the high-water mark where Halcyon sank into Pelagia's eastern shoals. Home to [[incarnate:raven|Raven]], [[incarnate:juniper|Juniper Vance]], [[incarnate:hattie|Hattie Lindqvist]], [[incarnate:brad|Brad]], [[incarnate:mark|Mark]], and Ray, with [[incarnate:siren|Siren]] and the hollowed remnant of [[incarnate:calypso|Calypso]] kept behind an iron grating in the tidal cellar below." },
    { id: "incarnate:leviathan-ribs", kind: "place", title: "The Leviathan Rib-Station", body: "A mudflat way-station built into the ribs of a beached leviathan along the six-mile abyssal causeway during Pelagia's Spring Ebb, kept by [[incarnate:ivy|Ivy Calder]], [[incarnate:dolly|Dolly Adore]], [[incarnate:noor|Noor]], and [[incarnate:conquest|Conquest]]." },
  );
  for (const [id, b] of [
    ["incarnate:wren", "On Pelagia she runs the Drift-Weir with her heavy pipe wrench and canvas bandage bag, hears [[incarnate:eri|Eri]]'s ungloved confession about [[incarnate:siren|Siren]], and carves whalebone splints for Eri's broken shins."],
    ["incarnate:pia", "Guards the outer stone breakwater of the Drift-Weir with the heavy salt-pitted iron cleaver [[incarnate:war|War]] forged from four years of swallowed arguments, fighting brine-hounds shoulder to shoulder with [[incarnate:harumi|Harumi]] in waist-deep freezing surf."],
    ["incarnate:esme", "At the Drift-Weir she is the first to tell [[incarnate:ena|Ena]] and [[incarnate:eri|Eri]] that Ena has no parasitic vessel: her mind split itself into four rooms (Ena, Harumi, Sunny, and Kio) to survive unbearable trauma."],
    ["incarnate:rui", "Tends a terraced volcanic orchard of salt-oranges at the bottom of Pelagia's basalt cliffs and carries a net bag up the steps every week to [[incarnate:tsui|Tsui]], who forgets her name every ten minutes and touches the hand-shaped burn scar on her jaw."],
    ["incarnate:tsui", "Lives in the whitewashed stone cottage atop the Cliff of Oranges; her memory resets with every tide from the vessel-chains, yet her eyes flicker blue for half a breath whenever Rui says *standing next to you*."],
    ["incarnate:famine", "Shelters in the volcanic sea-cave behind the Cliff of Oranges, her pale blue skin still scarred with frost-cracks, and weeps for the first time in three years when seven-year-old [[incarnate:sunny|Sunny]] shares a peeled salt-orange segment and kelp-bread with her after midnight."],
    ["incarnate:raven", "Keeps the Glass Shoals Lighthouse dry above the high-water mark, waking to charcoal notes written on her own forearms and recognizing Ena's hemp ledger as the same survival craft."],
    ["incarnate:juniper", "Walks the chalk-warded sea-wall at the Glass Shoals Lighthouse with [[incarnate:kio-soldier|Kio]], her forearms marked with 912 tiny white burn-scars."],
    ["incarnate:hattie", "Mends crab nets at the Glass Shoals Lighthouse and helps [[incarnate:sunny|Sunny]] count shells in twos and sevens."],
    ["incarnate:brad", "Lives at the Glass Shoals Lighthouse with [[incarnate:mark|Mark]] and Ray, still holding his own jaw with two fingers before answering any question after eleven days trapped behind his own face."],
    ["incarnate:mark", "Tends the low-tide mussel nets outside the Glass Shoals Lighthouse in his salt-stiffened leather jacket with a clapperless silver bell on his belt, and sits on the wet basalt steps with [[incarnate:ena|Ena]] to talk honestly about the unbearable shame of missing the song and the hum that ruined them."],
    ["incarnate:siren", "Kept in the tidal cellar beneath the Glass Shoals Lighthouse, her three-day-old draft-body peeling like wet parchment while she hums [[incarnate:wren|Wren]]'s river song in the dark, terrified of dying and going to the grey waiting room."],
    ["incarnate:calypso", "Washed up in the flooded cellar beneath the Glass Shoals Lighthouse stripped of the cosmic throat: a small, shivering girl in a salt-stiffened homecoming dress and bent tin crown scraping barnacles off the stone and whispering *that's mine* to an empty glass jar."],
    ["incarnate:ivy", "Lives at the Leviathan Rib-Station on the abyssal mudflats; having cut all eleven thousand leashes in the collapse, she speaks only in quiet questions so nobody can agree with her, still clutching [[incarnate:juno|Juno Pell]]'s rusted frog lunchbox."],
    ["incarnate:dolly", "Wears a triple-folded salt-cloth blindfold at the Leviathan Rib-Station so no stranger will ever look at her face and lose forty years of their life loving her by accident."],
    ["incarnate:noor", "Boils bitter kelp-tea at the Leviathan Rib-Station over the upside-down `KEEP OUT. THIS MEANS NOOR` door nailed across two salt barrels."],
    ["incarnate:conquest", "Sits at the Leviathan Rib-Station and Teodor's Hermitage fire without her white coat or horse, wearing the mended yellow paper crown with purple crayon stars."],
    ["incarnate:kaina", "Sits with [[incarnate:cosmi|Cosmi]] and [[incarnate:teodor|Teodor]] by the driftwood fire at the Hermitage above Pelagia's abyssal trench."],
    ["incarnate:tim", "His Purgatory stone statue stands at the bottom of Pelagia's drained abyssal salt-basin with barnacles and kelp over his stone boots; Ena, Harumi, Sunny, and Kio kneel co-consciously before it and carve *TIM. BROTHER. I'M SORRY. ME TOO.* into the wet granite plinth."],
  ]) add(id, { sections: [{ h: "In Book Two: The Salt and the Seam", b }] });
  TIMELINES.incarnate.push(["Book Two", "inc-b2", "The Salt and the Seam: Ena (and her alters Harumi, Sunny, and Kio) and Eri survive on the water world of Pelagia, confront their scars across the drowned archipelagos, and seal the abyssal Nursery fault."]);
  if (SERIES_LORE.incarnate?.sections) {
    SERIES_LORE.incarnate.sections.push({ h: "Book Two: The Salt and the Seam", b: "A full-length dark fantasy novel set on the drowned ocean world of **Pelagia**. Focusing deeply on [[incarnate:ena|Ena]]'s severe PTSD and realistic Dissociative Identity Disorder ([[incarnate:harumi|Harumi]], [[incarnate:sunny|Sunny]], and [[incarnate:kio-soldier|Kio]]) and [[incarnate:eri|Eri]]'s physical and psychological scars, it weaves every spinoff survivor into the archipelagos of Pelagia." });
  }
}

// ---------- v107: Backrooms: Episode Two · The Three Moons Initiative ----------
{
  const add = (id, extra) => Object.assign(CHARACTERS[id] || (CHARACTERS[id] = { title: extra.title, sections: [] }), extra.top || {}, { sections: [...(CHARACTERS[id].sections || []), ...extra.sections] });
  for (const [id, b] of [
    ["backrooms:mae", "In **Episode Two: The Three Moons Initiative**, the Foundation's Scranton Anchor network collapses on Summit Street and drops her, [[backrooms:leo|Leo]], and [[backrooms:kev|Kev]] back through Stall 44 into Level 11. Confronted with both the boy she left at the bottom of the ladder in Corbenic and the Skin-Stealer she let sit on her couch every Sunday, she refuses to leave anyone at the bottom of the ladder a third time, forging Kev his own B.N.T.G. courier coat at the Level 3999 terminal so both Kevins come home."],
    ["backrooms:kevin", "In **Episode Two: The Three Moons Initiative**, he hotwires Mae's portable Hume coil into his 2008 Honda Civic's alternator in the Bog of Corbenic and drives through **Level -1**, **Level 37 (The Poolrooms)**, **Level 974 (Kitty's House)**, **Level 404 (Dear Fragmented)**, and **The Blue Channel** with **[[backrooms:gat|Entity 59 (GAT)]]** on the roof rack, crashing through the Level 11 barricade outside Base Beta to confront [[backrooms:kev|the Skin-Stealer wearing his body]] and reclaim his living coat at the Level 3999 glass exit."],
    ["backrooms:leo", "In **Episode Two: The Three Moons Initiative**, he confronts Mae at Stall 44 about the Level 3 ladder and smashes the freezer jar of blue Jerry-fluid in front of the Flock during the siege of Base Beta, choosing his real, imperfect memories of his sister over the Bird's painless erasure."],
    ["backrooms:duke", "In **Episode Two: The Three Moons Initiative**, Mae pins him to Stall 44's filing-cabinet counter and reads his red-pen and frosting pages aloud, exposing how the Foundation trades 8.9 million annual noclippers to manufacture Level Keys from calcified human nostalgia."],
    ["backrooms:hays", "In **Episode Two: The Three Moons Initiative**, he and Medic Okonkwo defend Base Beta's bank vault against a dual siege by the Level Fun =) Host and Director Sterling's Followers of Jerry."],
    ["backrooms:jonah", "In **Episode Two: The Three Moons Initiative**, he leads thirty captives out of the Level Fun =) breach into Base Beta using a stolen Partypooper (`:(`) acoustic rig, confronts Mae for selling him for three flasks, and stays to run the front register at **Level 6.1 (The Snackrooms)** so every newcomer gets free Almond Water and keeps their name."],
    ["backrooms:sterling", "In **Episode Two: The Three Moons Initiative**, wheelchair-bound after Site-19, he leads an extraction team and the Followers of Jerry to Summit Street and Level 11 to restore the Foundation's 8.9-million-person pressure valve before his operation is broken at the Level 3999 Arcade."],
    ["backrooms:the-knight", "In **Episode Two: The Three Moons Initiative**, the sand-filled Grail Knight helps Kevin wire Mae's Scranton coil into the 2008 Honda Civic's alternator and lends its worn blade for the drive out of Corbenic."],
  ]) add(id, { sections: [{ h: "Episode Two: The Three Moons Initiative", b }] });
  CHARACTERS["backrooms:kev"] = { title: "Kev (With a V)", aka: ["“Kevin”", "The thing in the coat"], role: "Former Skin-Stealer; Columbus State CS student", firstIn: "br-sundays", sections: [{ h: "Who he is", b: "The Skin-Stealer who bought Duke's red-pen introduction to Room 318 at Riverside Methodist Hospital and came home wearing Kevin's body (**Sundays**). He brings Mountain Dew on Sundays, holds the Switch controller like a small animal, takes care of Denise at Kroger, gets a B+ in Intro to Python at Columbus State, and never eats a single Cool Ranch Dorito out of respect. In **Episode Two: The Three Moons Initiative**, he fights beside Mae and Real Kevin at Base Beta and the Level 3999 Arcade, returns Kevin's living body at the glass exit, and receives his own forged B.N.T.G. courier coat and student ID so both he and Kevin have a seat at Denny's." }] };
  CHARACTERS["backrooms:gat"] = { title: "Entity 59 (GAT)", aka: ["The Void-Cat"], role: "Subwoofer-purring eldritch soot-sprite", firstIn: "br-nwr-d4", sections: [{ h: "Who it is", b: "A massive, fuzzy black mass with giant white eyes that purrs like a subwoofer (`VRRRRRRRRRRUMMMMMM`), absorbs Cool Ranch Doritos with a soft *FOOMP*, and pops Level Fun balloons with a needle-thin shadow-whisker. In **Episode Two: The Three Moons Initiative**, it rides on the roof rack of Kevin's 2008 Honda Civic through the Blue Channel into Level 11." }] };
  CONCEPTS.push(
    { id: "backrooms:the-blue-channel", kind: "place", title: "The Blue Channel", body: "The infinite cobalt void between all Backrooms levels. In **Episode Two: The Three Moons Initiative**, Kevin drives his Hume-wired 2008 Honda Civic across its unrendered highway above Tiny (The Thing on Level 7) with [[backrooms:gat|GAT]] on the roof." },
    { id: "backrooms:level-404", kind: "place", title: "Level 404 (Dear Fragmented)", body: "A blinding expanse of broken white geometry and floating memory tapes where Subject 404 ([[backrooms:mae|Mae]]) left her excised memories during the Foundation's Denny's simulation." },
    { id: "backrooms:the-snackrooms", kind: "place", title: "Level 6.1 (The Snackrooms)", body: "A warm, neon-lit haven of diners and vending machines where [[backrooms:jonah|Jonah Reyes]] sets up a front-door register in **Episode Two: The Three Moons Initiative** to give every newly noclipped wanderer free Almond Water and record their real name." },
    { id: "backrooms:three-moons-initiative", kind: "concept", title: "The Three Moons Initiative (SCP-2922)", body: "The extra-universal force operating out of the Bog of Corbenic under three glowing moons (`YOU ARE BEING WATCHED. YOU ARE BEING PROTECTED.`). Mae's fused Scranton Reality Anchor armor carries its triple-moon crosshair, and its uplink guides Kevin's 2008 Honda Civic out of Corbenic in **Episode Two**." },
  );
  TIMELINES.backrooms.push(["Episode 2", "br-ep2", "The Three Moons Initiative: Sterling breaches Summit Street; Real Kevin drives his 2008 Civic out of Corbenic through Level 404 and the Blue Channel to Base Beta; both Kevins come home."]);
  if (SERIES_LORE.backrooms?.sections) {
    SERIES_LORE.backrooms.sections.push({ h: "Episode Two: The Three Moons Initiative", b: "A full-length sequel screenplay uniting the Columbus Frontrooms thread (**Sundays**, **Spatial Shift**), the Bog of Corbenic (**Corbenic**), and M.E.G. Base Beta (**Base Beta**, **Inventory**, **Party Favor**, **The Flock**) across Level 1, Level -1, the Poolrooms, Kitty's House, Level 404, the Blue Channel, Level 11, Level 3999, and the Snackrooms." });
  }
}
